/**
 * Types the JSON generated by scripts/i18n/build-ja-names.mjs (which is
 * committed, so this declaration is all TypeScript needs). The wildcard
 * only matches the one file, so other JSON imports stay unaffected.
 */
declare module "*/ja-names.json" {
  import type { JapaneseNames } from "@/data/display-names";

  const names: JapaneseNames;
  export default names;
}
